(function () {
  'use strict';
  // All skin-specific data comes from window.SKIN (js/skin.js), generated by builder.py.
  var SKIN = window.SKIN || {};

  var canvas = document.getElementById('stage');
  var fxRoot = document.getElementById('fx');
  var fxCanvas = document.getElementById('fxCanvas');
  var fxCtx = fxCanvas ? fxCanvas.getContext('2d') : null;
  var overlay = document.getElementById('hotspots');
  var subtitleEl = document.getElementById('subtitle');
  var loading = document.getElementById('loading');

  var ui = {
    zoom: 105, x: 50, y: 46, speed: 1, fpsLimit: 0,
    alignH: 'center', alignV: 'center', expression: 'normal',
    effects: true, bgm: true, bgmVolume: 40,
    voice: true, voiceVolume: 80,
    interaction: true, hints: false, greetOnStart: true,
    showSubtitles: true
  };

  var gl, renderer, skeleton, state;
  var hostPaused = false, occluded = false;
  var rafId = 0, lastFrame = null, lastFrameAt = 0;
  var globalFps = 0, lastRenderAt = 0;
  var vtNow = 0, expressionEndsAt = 0;
  var bgmAudio = null, voiceAudio = null, pausedBgm = false, pausedVoice = null;
  var greeted = false;
  var fallbackLast = -1;

  var ATLAS = SKIN.atlas;
  var SKEL = SKIN.skel;
  var TEXTURES = SKIN.textures || [];
  var ANIM = SKIN.anim || 'normal';
  var lines = SKIN.lines || {};
  var fallback = (SKIN.fallback || []).filter(function (key) { return !!lines[key]; });

  // Hit regions are fractions of the skeleton bounds (top-left origin): [x0, y0, x1, y1].
  var hits = [];
  if (SKIN.head && lines[SKIN.head.cue]) {
    hits.push({ id: 'head', cue: SKIN.head.cue, region: SKIN.head.region });
  }
  hits.push({ id: 'body', cue: null, region: (SKIN.body && SKIN.body.region) || [0, 0, 1, 1] });

  async function load(file) {
    var response = await fetch('assets/' + file);
    if (!response.ok) throw new Error('无法加载 ' + file);
    return response;
  }

  function loadImage(file) {
    return new Promise(function (resolve, reject) {
      var img = new Image();
      img.onload = function () { resolve(img); };
      img.onerror = function () { reject(new Error('无法加载 ' + file)); };
      img.src = 'assets/' + file;
    });
  }

  function viewSize() {
    return {
      w: window.innerWidth || document.documentElement.clientWidth || canvas.clientWidth || 1,
      h: window.innerHeight || document.documentElement.clientHeight || canvas.clientHeight || 1
    };
  }

  function flag(v) { return v === true || v === 1 || v === 'true' || v === '1'; }

  function slider(properties, key, min, max) {
    if (!properties[key]) return;
    var value = Number(properties[key].value);
    if (Number.isFinite(value)) ui[key] = Math.max(min, Math.min(max, value));
  }

  function comboValue(properties, key) {
    if (!properties[key]) return null;
    return properties[key].value;
  }

  var ALIGN_X = { left: 0, center: 50, right: 100 };
  var ALIGN_Y = { top: 0, center: 50, bottom: 100 };

  function resize() {
    if (!renderer) return;
    var size = viewSize(), w = size.w, h = size.h;
    var limits = gl.getParameter(gl.MAX_VIEWPORT_DIMS);
    var renderBuffer = gl.getParameter(gl.MAX_RENDERBUFFER_SIZE);
    var density = Math.min(3, limits[0] / w, limits[1] / h, renderBuffer / w, renderBuffer / h);
    canvas.width = Math.max(1, Math.floor(w * density));
    canvas.height = Math.max(1, Math.floor(h * density));
    gl.viewport(0, 0, canvas.width, canvas.height);
    fit();
  }

  function fit() {
    if (!renderer || !skeleton) return;
    var size = viewSize(), w = size.w, h = size.h;
    var off = new spine.Vector2(), sz = new spine.Vector2();
    skeleton.getBounds(off, sz);
    var bw = Math.max(sz.x, 1) * 0.96, bh = Math.max(sz.y, 1) * 0.96;
    var scale = Math.max(w / bw, h / bh) * 1.04 * (ui.zoom / 100);
    var camera = renderer.camera;
    camera.viewportWidth = w / scale;
    camera.viewportHeight = h / scale;
    var cx = off.x + bw / 2;
    var cy = off.y + bh / 2;
    camera.position.set(
      cx - (ui.x - 50) / 100 * camera.viewportWidth,
      cy + (ui.y - 50) / 100 * camera.viewportHeight,
      0
    );
    camera.update();
    drawHints();
  }

  /* ---------- Effects: procedural bokeh / star particles (canvas 2D, transparent over stage) ---------- */

  var fxParticles = [];
  var fxSprites = null;
  var fxLastT = 0;

  function makeSprite(size, draw) {
    var c = document.createElement('canvas');
    c.width = c.height = size;
    draw(c.getContext('2d'), size);
    return c;
  }

  function buildFxSprites() {
    var bokeh = makeSprite(128, function (g, s) {
      var r = s / 2;
      var grad = g.createRadialGradient(r, r, 0, r, r, r);
      grad.addColorStop(0, 'rgba(255,226,180,0.55)');
      grad.addColorStop(0.7, 'rgba(255,205,140,0.45)');
      grad.addColorStop(0.92, 'rgba(255,225,175,0.75)');
      grad.addColorStop(1, 'rgba(255,225,175,0)');
      g.fillStyle = grad;
      g.beginPath(); g.arc(r, r, r, 0, Math.PI * 2); g.fill();
    });
    var star = makeSprite(96, function (g, s) {
      var r = s / 2;
      var glow = g.createRadialGradient(r, r, 0, r, r, r * 0.45);
      glow.addColorStop(0, 'rgba(255,245,215,0.95)');
      glow.addColorStop(1, 'rgba(255,220,160,0)');
      g.fillStyle = glow;
      g.fillRect(0, 0, s, s);
      g.fillStyle = 'rgba(255,248,225,0.95)';
      g.beginPath();
      g.moveTo(r, 2); g.lineTo(r + 3, r - 3); g.lineTo(s - 2, r); g.lineTo(r + 3, r + 3);
      g.lineTo(r, s - 2); g.lineTo(r - 3, r + 3); g.lineTo(2, r); g.lineTo(r - 3, r - 3);
      g.closePath(); g.fill();
    });
    var dot = makeSprite(24, function (g, s) {
      var r = s / 2;
      var grad = g.createRadialGradient(r, r, 0, r, r, r);
      grad.addColorStop(0, 'rgba(255,240,205,1)');
      grad.addColorStop(0.35, 'rgba(255,205,130,0.85)');
      grad.addColorStop(1, 'rgba(255,190,110,0)');
      g.fillStyle = grad;
      g.fillRect(0, 0, s, s);
    });
    return { bokeh: bokeh, star: star, dot: dot };
  }

  function rnd(a, b) { return a + Math.random() * (b - a); }

  function spawnParticle(kind) {
    var p = { kind: kind, x: Math.random(), y: rnd(0.4, 1.05), ph: Math.random() * 6.283 };
    if (kind === 'bokeh') {
      p.s = rnd(0.018, 0.05); p.vy = -rnd(0.004, 0.012); p.sw = rnd(0.004, 0.012); p.a = rnd(0.5, 0.95); p.sp = rnd(0.25, 0.7);
    } else if (kind === 'star') {
      p.s = rnd(0.035, 0.08); p.vy = -rnd(0.001, 0.006); p.sw = rnd(0.002, 0.006); p.a = 1; p.sp = rnd(0.9, 2.2);
    } else {
      p.s = rnd(0.007, 0.018); p.vy = -rnd(0.006, 0.02); p.sw = rnd(0.004, 0.012); p.a = 1; p.sp = rnd(0.6, 1.6);
    }
    return p;
  }

  function initEffects() {
    fxSprites = buildFxSprites();
    fxParticles = [];
    var i;
    for (i = 0; i < 8; i++) fxParticles.push(spawnParticle('bokeh'));
    for (i = 0; i < 6; i++) fxParticles.push(spawnParticle('star'));
    for (i = 0; i < 22; i++) fxParticles.push(spawnParticle('dot'));
    fxLastT = 0;
    setEffectsEnabled(ui.effects);
  }

  function resizeFxCanvas() {
    if (!fxCanvas) return;
    var size = viewSize();
    var w = Math.max(1, Math.floor(size.w * 0.75));
    var h = Math.max(1, Math.floor(size.h * 0.75));
    if (fxCanvas.width !== w || fxCanvas.height !== h) {
      fxCanvas.width = w;
      fxCanvas.height = h;
    }
  }

  function drawEffects(now) {
    if (!fxCtx || !fxSprites || !ui.effects || hostPaused) return;
    resizeFxCanvas();
    var t = (now || performance.now()) / 1000;
    var dt = fxLastT ? Math.min(0.1, t - fxLastT) : 0;
    fxLastT = t;
    var tw = fxCanvas.width, th = fxCanvas.height;
    fxCtx.clearRect(0, 0, tw, th);
    for (var i = 0; i < fxParticles.length; i++) {
      var p = fxParticles[i];
      p.y += p.vy * dt;
      if (p.y < 0.3) { p.y = 1.06; p.x = Math.random(); }
      var tw2 = 0.5 + 0.5 * Math.sin(t * p.sp * 2 + p.ph);
      var alpha = p.kind === 'star' ? Math.pow(tw2, 2) : p.a * (0.55 + 0.45 * tw2);
      var lowerFade = Math.max(0, Math.min(1, (p.y - 0.35) / 0.3));
      alpha *= lowerFade;
      if (alpha < 0.02) continue;
      var px = (p.x + Math.sin(t * p.sp * 0.6 + p.ph) * p.sw) * tw;
      var py = p.y * th;
      var d = p.s * th * (p.kind === 'star' ? (0.6 + 0.4 * tw2) : 1);
      fxCtx.globalAlpha = Math.min(1, alpha);
      fxCtx.drawImage(fxSprites[p.kind], px - d / 2, py - d / 2, d, d);
    }
    fxCtx.globalAlpha = 1;
  }

  function setEffectsEnabled(enabled) {
    ui.effects = !!enabled;
    if (!fxRoot) return;
    fxRoot.hidden = !ui.effects;
    if (!ui.effects && fxCtx) fxCtx.clearRect(0, 0, fxCanvas.width, fxCanvas.height);
  }

  /* ---------- Audio ---------- */

  function stopVoice() {
    if (voiceAudio) {
      try { voiceAudio.pause(); } catch (e) { }
    }
    voiceAudio = null;
    pausedVoice = null;
    hideSubtitle();
  }

  function setVoiceVolume(vol01) {
    if (voiceAudio) voiceAudio.volume = Math.max(0, Math.min(1, vol01));
  }

  function hushIfSuspended(audio, kind) {
    if (!audio || !(hostPaused || occluded)) return false;
    try { audio.pause(); } catch (e) { }
    if (kind === 'voice') pausedVoice = audio;
    if (kind === 'bgm') pausedBgm = true;
    return true;
  }

  function hideSubtitle() {
    if (!subtitleEl) return;
    subtitleEl.hidden = true;
    subtitleEl.textContent = '';
  }

  function showSubtitle(text) {
    if (!subtitleEl) return;
    if (!ui.showSubtitles || !text) {
      hideSubtitle();
      return;
    }
    subtitleEl.textContent = text;
    subtitleEl.hidden = false;
  }

  function playVoice(key) {
    var line = key ? lines[key] : null;
    if (!line) return;
    if (hostPaused || occluded) return;
    stopVoice();
    if (state && line.expression) {
      try {
        var entry = state.setAnimation(1, String(line.expression), false);
        entry.mixDuration = 0.15;
      } catch (e) { }
      expressionEndsAt = 0;
    }
    showSubtitle(line.text);
    if (!ui.voice || !line.file) {
      scheduleExpressionClear(4);
      return;
    }
    var audio = new Audio('assets/voice/' + line.file);
    audio.volume = ui.voiceVolume / 100;
    voiceAudio = audio;
    audio.onended = function () {
      if (voiceAudio === audio) {
        voiceAudio = null;
        clearExpressionTrack();
      }
    };
    audio.play().then(function () {
      if (hushIfSuspended(audio, 'voice')) return;
      scheduleExpressionClear((audio.duration && isFinite(audio.duration) ? audio.duration : 4) + 0.2);
    }).catch(function () {
      scheduleExpressionClear(3);
    });
    window.__LAST_CUE__ = key;
  }

  function scheduleExpressionClear(seconds) {
    expressionEndsAt = vtNow + Math.max(0.5, seconds) * 1000;
  }

  function clearExpressionTrack() {
    expressionEndsAt = 0;
    hideSubtitle();
    if (!state) return;
    if (!ui.expression || ui.expression === 'normal') {
      state.setEmptyAnimation(1, 0.15);
    } else {
      try {
        var entry = state.setAnimation(1, ui.expression, false);
        entry.mixDuration = 0.2;
      } catch (e) {
        state.setEmptyAnimation(1, 0.15);
      }
    }
  }

  function stopBgm() {
    if (bgmAudio) {
      try { bgmAudio.pause(); } catch (e) { }
    }
    pausedBgm = false;
  }

  function setBgmVolume(vol01) {
    if (bgmAudio) bgmAudio.volume = Math.max(0, Math.min(1, vol01));
  }

  function playBgm() {
    if (!SKIN.bgm) return;
    if (!ui.bgm) { stopBgm(); return; }
    if (!bgmAudio) {
      bgmAudio = new Audio('assets/' + SKIN.bgm);
      bgmAudio.loop = true;
    }
    bgmAudio.volume = ui.bgmVolume / 100;
    if (hostPaused || occluded) {
      pausedBgm = true;
      return;
    }
    bgmAudio.play().then(function () {
      hushIfSuspended(bgmAudio, 'bgm');
    }).catch(function () {});
  }

  function audioPauseAll(force) {
    if (!force && occluded) {
      // Watchdog: a play() that resolved after the first pause must still be hushed.
      try {
        if (voiceAudio && !voiceAudio.ended && !voiceAudio.paused) {
          pausedVoice = voiceAudio;
          voiceAudio.pause();
        }
      } catch (e0) { }
      try {
        if (bgmAudio && !bgmAudio.paused) {
          pausedBgm = true;
          bgmAudio.pause();
        }
      } catch (e0b) { }
      return;
    }
    occluded = true;
    try {
      if (voiceAudio && !voiceAudio.ended) {
        pausedVoice = voiceAudio;
        voiceAudio.pause();
      }
    } catch (e1) { }
    try {
      if (bgmAudio) {
        pausedBgm = true;
        bgmAudio.pause();
      }
    } catch (e2) { }
    window.__OCCLUDED__ = true;
  }

  function audioResumeAll() {
    if (hostPaused) return;
    if (!occluded) return;
    occluded = false;
    try {
      if (pausedVoice && !pausedVoice.ended) {
        pausedVoice.play().catch(function () {});
      }
    } catch (e1) { }
    pausedVoice = null;
    try {
      if (ui.bgm && bgmAudio && pausedBgm) {
        bgmAudio.play().catch(function () {});
      }
    } catch (e2) { }
    pausedBgm = false;
    window.__OCCLUDED__ = false;
  }

  /* ---------- Hits ---------- */

  function computeHits() {
    var off = new spine.Vector2(), sz = new spine.Vector2();
    skeleton.getBounds(off, sz);
    var W = Math.max(sz.x, 1), H = Math.max(sz.y, 1);
    hits.forEach(function (hit) {
      var r = hit.region;
      var left = off.x + r[0] * W, right = off.x + r[2] * W;
      var top = off.y + H - r[1] * H, bottom = off.y + H - r[3] * H;
      hit.x = (left + right) / 2;
      hit.y = (top + bottom) / 2;
      hit.width = Math.max(right - left, 1);
      hit.height = Math.max(top - bottom, 1);
    });
  }

  function project(box) {
    if (!box || !renderer) return null;
    var size = viewSize();
    var camera = renderer.camera;
    var xScale = size.w / camera.viewportWidth;
    var yScale = size.h / camera.viewportHeight;
    return {
      x: size.w / 2 + (box.x - box.width / 2 - camera.position.x) * xScale,
      y: size.h / 2 + (camera.position.y - box.y - box.height / 2) * yScale,
      width: box.width * xScale,
      height: box.height * yScale
    };
  }

  function drawHints() {
    if (!overlay) return;
    overlay.hidden = !ui.hints || !skeleton;
    if (overlay.hidden) return;
    hits.forEach(function (hit, i) {
      var box = project(hit);
      var element = overlay.children[i];
      if (!element) return;
      element.hidden = !box;
      if (!box) return;
      element.style.left = box.x + 'px';
      element.style.top = box.y + 'px';
      element.style.width = box.width + 'px';
      element.style.height = box.height + 'px';
    });
  }

  function pickFallback() {
    if (!fallback.length) return null;
    var index = Math.floor(Math.random() * (fallback.length - (fallbackLast < 0 ? 0 : 1)));
    if (fallbackLast >= 0 && index >= fallbackLast) index++;
    fallbackLast = index;
    return fallback[index];
  }

  function onPointer(event) {
    if (!ui.interaction || event.button !== 0 || !skeleton) return;
    var rect = canvas.getBoundingClientRect();
    var x = event.clientX - rect.left, y = event.clientY - rect.top;
    var hit = hits.find(function (candidate) {
      var box = project(candidate);
      return box && x >= box.x && x <= box.x + box.width && y >= box.y && y <= box.y + box.height;
    });
    if (hit) playVoice(hit.cue || pickFallback());
  }

  /* ---------- Loop / pause ---------- */

  function stopLoop() {
    if (rafId) { try { cancelAnimationFrame(rafId); } catch (e) { } rafId = 0; }
    lastFrame = null;
  }

  function applyHostPaused(paused) {
    hostPaused = !!paused;
    window.__HOSTPAUSED__ = hostPaused;
    if (hostPaused) {
      audioPauseAll(true);
      stopLoop();
    } else {
      lastFrameAt = performance.now();
      audioResumeAll();
      startLoop();
    }
  }

  function watchOcclusion() {
    if (!skeleton || hostPaused) return;
    var gap = performance.now() - lastFrameAt;
    if (!occluded && lastFrameAt > 0 && gap > 600) { audioPauseAll(); }
    else if (occluded && gap < 250) { audioResumeAll(); }
  }

  function frame(now) {
    rafId = 0;
    if (hostPaused) { lastFrame = null; return; }
    var activeFps = ui.fpsLimit > 0 ? ui.fpsLimit : globalFps;
    var minInterval = activeFps > 0 ? 1000 / activeFps : 0;
    if (minInterval > 0 && lastRenderAt > 0 && now - lastRenderAt < minInterval - 1) {
      rafId = requestAnimationFrame(frame);
      return;
    }
    lastRenderAt = now;
    var dt = lastFrame === null ? 0 : Math.min(0.1, (now - lastFrame) / 1000);
    lastFrame = now;
    lastFrameAt = performance.now();
    vtNow += dt * 1000;
    if (expressionEndsAt && vtNow >= expressionEndsAt) {
      clearExpressionTrack();
    }
    state.update(dt * ui.speed);
    state.apply(skeleton);
    skeleton.updateWorldTransform();
    gl.clear(gl.COLOR_BUFFER_BIT);
    renderer.begin();
    renderer.drawSkeleton(skeleton, true);
    renderer.end();
    drawEffects(now);
    if (ui.hints) drawHints();
    rafId = requestAnimationFrame(frame);
  }

  function startLoop() {
    if (rafId || hostPaused) return;
    lastFrame = null;
    rafId = requestAnimationFrame(frame);
  }

  function applyExpression() {
    if (!state) return;
    if (!ui.expression || ui.expression === 'normal') {
      state.clearTrack(1);
    } else {
      try {
        var entry = state.setAnimation(1, ui.expression, false);
        entry.mixDuration = 0.2;
      } catch (e) { }
    }
  }

  window.wallpaperPropertyListener = {
    setPaused: function (paused) { applyHostPaused(paused); },
    applyGeneralProperties: function (properties) {
      if (properties.fps) { globalFps = Number(properties.fps.value) || 0; }
    },
    applyUserProperties: function (properties) {
      slider(properties, 'zoom', 50, 200);
      slider(properties, 'x', 0, 100);
      slider(properties, 'y', 0, 100);
      slider(properties, 'speed', 0.2, 2);
      if (properties.fpsLimit) { ui.fpsLimit = Number(properties.fpsLimit.value) || 0; }
      var ex = comboValue(properties, 'expression');
      if (ex !== null) { ui.expression = ex; if (!expressionEndsAt) applyExpression(); }
      var ah = comboValue(properties, 'alignH');
      if (ah !== null && ALIGN_X[ah] !== undefined) { ui.alignH = ah; ui.x = ALIGN_X[ah]; }
      var av = comboValue(properties, 'alignV');
      if (av !== null && ALIGN_Y[av] !== undefined) { ui.alignV = av; ui.y = ALIGN_Y[av]; }

      if (properties.effects) setEffectsEnabled(flag(properties.effects.value));
      if (properties.bgm) {
        ui.bgm = flag(properties.bgm.value);
        if (ui.bgm) playBgm(); else stopBgm();
      }
      if (properties.bgmVolume) {
        ui.bgmVolume = Number(properties.bgmVolume.value) || 0;
        setBgmVolume(ui.bgmVolume / 100);
      }
      if (properties.voice) {
        ui.voice = flag(properties.voice.value);
        if (!ui.voice) stopVoice();
      }
      if (properties.voiceVolume) {
        ui.voiceVolume = Number(properties.voiceVolume.value) || 0;
        setVoiceVolume(ui.voiceVolume / 100);
      }
      if (properties.interaction) {
        ui.interaction = flag(properties.interaction.value);
        if (!ui.interaction) {
          stopVoice();
          if (state && expressionEndsAt) clearExpressionTrack();
        }
      }
      if (properties.hints) {
        ui.hints = flag(properties.hints.value);
        drawHints();
      }
      if (properties.greetOnStart) ui.greetOnStart = flag(properties.greetOnStart.value);
      if (properties.showSubtitles) {
        ui.showSubtitles = flag(properties.showSubtitles.value);
        if (!ui.showSubtitles) hideSubtitle();
      }
      fit();
    }
  };

  window.__AV__ = function () {
    return {
      hostPaused: hostPaused,
      occluded: occluded,
      vt: Math.round(vtNow),
      cue: window.__LAST_CUE__ || '',
      effects: ui.effects,
      bgm: bgmAudio ? { paused: bgmAudio.paused, t: +bgmAudio.currentTime.toFixed(2) } : null,
      voice: voiceAudio ? { paused: voiceAudio.paused, t: +voiceAudio.currentTime.toFixed(2) } : null,
      raf: !!rafId
    };
  };

  async function init() {
    gl = canvas.getContext('webgl', { alpha: true, antialias: false, premultipliedAlpha: true });
    if (!gl) throw new Error('无法创建 WebGL 场景');
    renderer = new spine.webgl.SceneRenderer(canvas, gl);
    gl.clearColor(0, 0, 0, 0);

    var results = await Promise.all([
      load(ATLAS).then(function (r) { return r.text(); }),
      load(SKEL).then(function (r) { return r.arrayBuffer(); }),
      Promise.all(TEXTURES.map(loadImage))
    ]);

    var pages = {};
    TEXTURES.forEach(function (name, i) { pages[name] = results[2][i]; });
    var atlas = new spine.TextureAtlas(results[0].trimStart().replace(/^pma:.*\r?\n/gm, ''), function (name) {
      if (!pages[name]) throw new Error('图集缺少 ' + name);
      return new spine.webgl.GLTexture(gl, pages[name]);
    });
    var data = new spine.SkeletonBinary(new spine.AtlasAttachmentLoader(atlas))
      .readSkeletonData(new Uint8Array(results[1]));
    skeleton = new spine.Skeleton(data);
    if (SKIN.skinName) {
      try { skeleton.setSkinByName(SKIN.skinName); } catch (e) { }
    }
    skeleton.setToSetupPose();
    skeleton.updateWorldTransform();
    var settings = new spine.AnimationStateData(data);
    settings.defaultMix = 0.2;
    state = new spine.AnimationState(settings);
    state.setAnimation(0, ANIM, true);
    state.update(0);
    state.apply(skeleton);
    skeleton.updateWorldTransform();

    // Hotspot overlay boxes (debug only, shown when the "hints" property is on).
    computeHits();
    hits.forEach(function (hit) {
      var box = document.createElement('div');
      box.className = 'hotspot';
      box.dataset.hit = hit.id;
      overlay.appendChild(box);
    });

    initEffects();
    resize();
    window.addEventListener('resize', resize);
    canvas.addEventListener('pointerdown', onPointer);

    lastFrameAt = performance.now();
    setInterval(watchOcclusion, 150);
    document.addEventListener('visibilitychange', function () {
      if (document.hidden) { audioPauseAll(); }
      else { lastFrameAt = performance.now(); audioResumeAll(); }
    });

    startLoop();
    playBgm();
    loading.hidden = true;
    window.__READY__ = true;

    if (ui.greetOnStart && !greeted && SKIN.greet && lines[SKIN.greet]) {
      greeted = true;
      setTimeout(function () {
        if (ui.greetOnStart && !hostPaused && !occluded) playVoice(SKIN.greet);
      }, 400);
    }
  }

  init().catch(function (error) {
    window.__ERR__ = String(error && error.stack || error);
    loading.textContent = error.message || '壁纸加载失败';
    console.error(error);
  });
})();
